function validate([transactions]) {
  if (!Array.isArray(transactions) || transactions.length < 1 || transactions.length > 8) return 'transactions needs 1 to 8 entries.';
  for (const t of transactions) {
    if (!Array.isArray(t) || t.length !== 3 || !t.every(Number.isInteger)) return 'Each transaction is [from, to, amount] with integers.';
    const [from, to, amount] = t;
    if (from < 0 || from >= 12 || to < 0 || to >= 12) return 'Person IDs are between 0 and 11.';
    if (from === to) return 'A transaction needs two different people.';
    if (amount < 1 || amount > 100) return 'Each amount is between 1 and 100.';
  }
  return null;
}

