function minTransfers(transactions) {
  const balance = new Map();
  for (const [from, to, amount] of transactions) {
    balance.set(from, (balance.get(from) ?? 0) - amount);
    balance.set(to, (balance.get(to) ?? 0) + amount);
  }
  const debts = [...balance.values()].filter(value => value !== 0);

  const settle = (start) => {
    while (start < debts.length && debts[start] === 0) {
      start++;
    }
    if (start === debts.length) {
      return 0;
    }
    let best = Infinity;
    for (let next = start + 1; next < debts.length; next++) {
      if (debts[next] * debts[start] >= 0) {
        continue;
      }
      debts[next] += debts[start];
      best = Math.min(best, 1 + settle(start + 1));
      debts[next] -= debts[start];
      if (debts[next] === -debts[start]) {
        break;
      }
    }
    return best;
  };

  return settle(0);
}

