function minTransfers(transactions) {
  // Bitmask DP: the answer is (people with a nonzero balance) minus the most zero-sum groups they split into.
  const net = new Array(12).fill(0);
  for (const [a, b, c] of transactions) { net[a] -= c; net[b] += c; }
  const vals = net.filter(v => v !== 0);
  const n = vals.length, full = (1 << n) - 1;
  const sum = new Array(full + 1).fill(0), groups = new Array(full + 1).fill(0);
  for (let mask = 1; mask <= full; mask++) {
    const low = mask & -mask;
    sum[mask] = sum[mask ^ low] + vals[31 - Math.clz32(low)];
    let most = 0;
    for (let j = 0; j < n; j++) if (mask & (1 << j)) most = Math.max(most, groups[mask ^ (1 << j)]);
    groups[mask] = most + (sum[mask] === 0 ? 1 : 0);
  }
  return n - groups[full];
}

