function generate(rand, size) {
  const count = size === 'large' ? 8 : 1 + Math.floor(rand() * 7);
  const people = size === 'large' ? 12 : 2 + Math.floor(rand() * 6);
  // Small amounts make balances cancel in interesting ways; large ones make them all distinct.
  const top = [3, 10, 100][Math.floor(rand() * 3)];
  const transactions = [];
  for (let t = 0; t < count; t++) {
    const from = Math.floor(rand() * people);
    let to = Math.floor(rand() * (people - 1));
    if (to >= from) to++;
    transactions.push([from, to, 1 + Math.floor(rand() * top)]);
  }
  return [transactions];
}
